select #{dates} dates, u.id user_id, u.dates register_dates, u.create_time register_date, u.pkg, u.last_login create_time, min(uv.pvn) register_version, max(uv.pvn) version, IFNULL(uh.address, 'IN') country, TIMESTAMPDIFF(DAY, u.create_time, u.last_login) register_cohort_day, TIMESTAMPDIFF(DAY, u.dates, #{dates}) register_day from diversion.user u INNER JOIN diversion.user_version uv on (uv.user_id = u.id and uv.dates <= #{dates}) left join diversion.user_hema uh on (u.aid = uh.aid and uh.pkg = u.pkg) where u.id in
#{item}
group by u.id, u.dates, u.pkg, u.create_time, u.last_login, IFNULL(uh.address, 'IN') union select #{dates} dates, u.id user_id, u.dates register_dates, u.create_time register_date, u.pkg, u.last_login create_time, min(huv.pvn) register_version, max(huv.pvn) version, IFNULL(uh.address, 'IN') country, TIMESTAMPDIFF(DAY, u.create_time, u.last_login) register_cohort_day, TIMESTAMPDIFF(DAY, u.dates, #{dates}) register_day from diversion.user u INNER JOIN diversion.user_version uv on (uv.user_id = u.id and uv.dates = #{dates}) INNER JOIN diversion.user_version huv on (huv.user_id = u.id and huv.dates < #{dates} ) left join diversion.user_hema uh on (u.aid = uh.aid and uh.pkg = u.pkg) where u.id in
